style.css:
@-moz-document domain("claude.ai") {
/* ---------- Palette ----------
     pudding yellow  #FFE08A
     cream           #FFF8E1
     caramel         #C98A3D
     beret brown     #8B5A2B
     chocolate       #4A2F1A
  ------------------------------- */

  /* ---------- LIGHT MODE ---------- */
  :root,
  [data-mode="light"],
  [data-theme] {
    --bg-000: 48 100% 97%;
    --bg-100: 46 100% 94%;
    --bg-200: 45 90% 89%;
    --bg-300: 43 80% 83%;
    --bg-400: 41 70% 76%;
    --bg-500: 39 60% 68%;

    --text-000: 25 45% 16%;
    --text-100: 25 42% 20%;
    --text-200: 27 36% 30%;
    --text-300: 29 30% 40%;
    --text-400: 30 26% 48%;
    --text-500: 30 22% 56%;

    --accent-brand: 33 58% 50%;
    --accent-main-000: 30 55% 42%;
    --accent-main-100: 33 58% 48%;
    --accent-main-200: 36 62% 54%;
    --accent-pro-000: 30 55% 42%;
    --accent-pro-100: 33 58% 48%;
    --accent-pro-200: 36 62% 54%;

    --border-100: 35 50% 60%;
    --border-200: 35 50% 60%;
    --border-300: 35 50% 60%;
    --border-400: 35 50% 60%;
  }

  /* ---------- DARK MODE (warm chocolate pudding) ---------- */
  [data-mode="dark"] {
    --bg-000: 25 30% 11%;
    --bg-100: 25 28% 14%;
    --bg-200: 25 26% 17%;
    --bg-300: 25 24% 21%;
    --bg-400: 25 22% 26%;
    --bg-500: 25 20% 32%;

    --text-000: 46 100% 90%;
    --text-100: 46 90% 85%;
    --text-200: 44 70% 76%;
    --text-300: 42 50% 66%;
    --text-400: 40 38% 56%;
    --text-500: 38 30% 46%;

    --accent-brand: 42 95% 68%;
    --accent-main-000: 42 95% 62%;
    --accent-main-100: 42 95% 68%;
    --accent-main-200: 44 100% 74%;
    --accent-pro-000: 42 95% 62%;
    --accent-pro-100: 42 95% 68%;
    --accent-pro-200: 44 100% 74%;

    --border-100: 33 40% 40%;
    --border-200: 33 40% 40%;
    --border-300: 33 40% 40%;
    --border-400: 33 40% 40%;
  }

  /* ---------- Page background ---------- */
  html, body {
    background-color: hsl(var(--bg-100)) !important;
  }

  /* subtle polka-dot pudding pattern (light mode only) */
  html:not([data-mode="dark"]) body {
    background-image: radial-gradient(hsl(var(--bg-300) / 0.55) 2px, transparent 2px);
    background-size: 28px 28px;
  }

  /* ---------- Cuteness ---------- */
  ::selection {
    background: #FFE08A;
    color: #4A2F1A;
  }

  /* rounder everything */
  button,
  textarea,
  input,
  [role="dialog"],
  [role="menu"] {
    border-radius: 16px !important;
  }

  /* chat input gets a caramel glow */
  fieldset,
  [contenteditable="true"] {
    caret-color: #C98A3D;
  }
  fieldset {
    border-radius: 24px !important;
    box-shadow: 0 4px 18px rgba(201, 138, 61, 0.25) !important;
    border: 2px solid hsl(var(--border-100)) !important;
  }

  /* links */
  a { color: hsl(var(--accent-main-100)); }
  a:hover { color: hsl(var(--accent-main-000)); }

  /* code blocks look like little pudding cups */
  pre {
    border-radius: 14px !important;
    border: 1.5px dashed hsl(var(--border-100)) !important;
  }

  /* friendly scrollbars */
  * {
    scrollbar-width: thin;
    scrollbar-color: #C98A3D transparent;
  }
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-thumb {
    background: #C98A3D;
    border-radius: 10px;
    border: 2px solid transparent;
    background-clip: content-box;
  }

  /* little pudding in the corner */
  body::after {
    content: "?";
    position: fixed;
    right: 14px;
    bottom: 10px;
    font-size: 26px;
    opacity: 0.85;
    pointer-events: none;
    z-index: 9999;
    animation: purin-bounce 2.4s ease-in-out infinite;
  }
  @keyframes purin-bounce {
    0%, 100% { transform: translateY(0) rotate(-4deg); }
    50%      { transform: translateY(-6px) rotate(4deg); }
  }
}
